import '@awesome.me/webawesome/dist/components/button/button.js';
import '@awesome.me/webawesome/dist/components/badge/badge.js';
import '@awesome.me/webawesome/dist/components/progress-bar/progress-bar.js';
import '@awesome.me/webawesome/dist/components/input/input.js';
import '@awesome.me/webawesome/dist/components/details/details.js';
import { windows, total, time, money, day, now, priceAt } from './sample.js';
import { mountCharts } from './charts.js';

const card = (title, eyebrow, content, cls = '') => `<section class="panel ${cls}"><header class="panel-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><span class="sample-tag">SAMPLE</span></header>${content}</section>`;
const metric = (label, value, note) => `<div class="metric"><div class="muted">${label}</div><strong>${value}</strong><div class="muted">${note}</div></div>`;
const summary = total(windows);
const rows = windows.map((w, i) => `<div class="plan-row"><span><b>${time(w.start)}–${time(w.end)}</b><small>${day(w.start)}${i === 0 ? ' · NEXT' : ''}</small></span><span><b>${(w.cost * 100 / w.energy).toFixed(1)} c/kWh</b><small>window price</small></span><span><b>${w.energy.toFixed(1)} kWh</b><small>estimated</small></span><span><b>${money(w.cost)}</b><small>estimated</small></span></div>`).join('');
document.querySelector('#app').innerHTML = `
<div class="shell"><header class="masthead"><div><div class="brand">SPOTNAV <span>ENHANCED</span></div><h1>Charging, in focus.</h1><p>A single view of your vehicle, plan and charger.</p></div><div class="sample-banner">DESIGN PROTOTYPE · SAMPLE DATA<br><span>Offline illustration — no charger connection</span></div></header>
<div class="alert" role="status"><div><strong>Schedule needs attention</strong><p>Sample charger limits differ from the last sent plan. Charging cannot be confirmed from that response.</p></div><a href="#details">View details ↓</a></div>
<div class="dashboard">
${card('Your vehicle', 'OVERVIEW', `<div class="vehicle-top"><div><div class="status-line"><span class="dot"></span> Connected · waiting to charge</div><div class="soc">48<span>%</span></div><p class="muted">Sample battery level</p></div><div class="target">Target <strong>80%</strong><span>Minimum 40% · by 07:00</span></div></div><wa-progress-bar value="48" aria-label="Sample battery level 48 percent"></wa-progress-bar><p class="waiting">Waiting for the first lower-price window. This is a proposal, not a guarantee of charging.</p><div class="metrics">${metric('Measured now','0.0 kW','Sample reading, not unavailable')}${metric('Next proposed window','22:00–23:00','Tonight · sample')}${metric('Active charging','2h 30m','Estimated plan time')}${metric('Until deadline','10h','07:00 deadline, not predicted finish')}</div><div class="hint"><b>Minimum already met.</b> Target not projected to be reached within the cap: 15 kWh planned vs 21.3 kWh estimated needed. Sample assumptions: 60 kWh usable battery, 90% efficiency.</div>`, 'overview')}
${card('Prices & plan', 'CHART DESIGN COMPARISON', `<div class="chart-intro"><div><strong>Compare two price views</strong><p>Same fictional published prices · EUR variable cost incl. fees & taxes</p></div><wa-badge variant="brand" pill>Sample</wa-badge></div><div class="chart-switch" role="group" aria-label="Choose chart design"><wa-button data-chart-mode="bar" variant="brand" aria-pressed="true">A · Bars</wa-button><wa-button data-chart-mode="step" variant="neutral" aria-pressed="false">B · Stepped area</wa-button></div><div class="price-context"><span>Now · <b>${priceAt(now).cents.toFixed(1)} c/kWh</b></span><span>Next proposed · <b>−2.0 c/kWh</b></span></div><p id="chart-description" class="chart-description">A · Interval-width bars</p><div id="price-chart" class="chart price-chart" role="img" aria-label="Fictional interval electricity prices, negative prices, plan windows and cap, now and deadline markers"></div><div class="chart-actions"><wa-button id="zoom-in" size="small">Zoom in</wa-button><wa-button id="zoom-reset" size="small">Reset overview</wa-button><span>Drag overview handles or chart to pan · scroll / pinch to zoom</span></div><p class="legend"><span class="swatch"></span> Published sample price <span class="shade"></span> Proposed window <span class="cap-key"></span> Cap 10 c/kWh</p><p class="subtext">Yesterday, today and published future shown. Grey bands: missing today 14:00–15:00 and tomorrow after 12:00. Unknown is not zero. Low-price opportunities are not necessarily the proposed plan.</p><div class="plan-heading"><div><h3>Complete proposed plan</h3><p>Estimated wall energy and cost · EUR</p></div><wa-badge variant="neutral" pill>3 windows</wa-badge></div><div class="plan-label"><span>Window</span><span>Price</span><span>Energy</span><span>Cost</span></div>${rows}<div class="plan-total"><div><small>THIS CHARGE · ESTIMATED</small><strong>${summary.energy.toFixed(1)} kWh</strong></div><div><small>TOTAL COST</small><strong>${money(summary.cost)}</strong></div><div><small>AVERAGE PRICE</small><strong>${summary.centsPerKwh.toFixed(2)} c/kWh</strong></div></div><p class="subtext">All three sample prices are at or below the 10 c/kWh cap. The minimum is already met, so no above-cap exception is needed.</p>`, 'prices')}
${card('Plan controls', 'SIMULATED SETTINGS', `<p class="subtext">Illustrative inputs only. Changes do not recalculate or save a plan.</p><div class="fields"><wa-input label="Target SOC (%)" value="80" type="number"></wa-input><wa-input label="Minimum SOC (%)" value="40" type="number"></wa-input><wa-input label="Soft cap (€/kWh)" value="0.10" type="number" step="0.01"></wa-input><wa-input label="Ready by" value="07:00" type="time"></wa-input></div><wa-button variant="brand" disabled>Save plan · unavailable</wa-button>`, 'controls')}
${card('Charger health', 'DAILY STATUS', `<div class="health"><strong>Needs attention</strong><p>The sample reported limits do not match the last sent schedule. Check the details before relying on the plan.</p></div><p class="subtext">Autonomous dispatch is unarmed. Neither an accepted response nor reported limits prove physical charging.</p><wa-details id="details" summary="View sample evidence & debug controls"><div class="details-body"><p><b>Proposal:</b> Three windows calculated; not necessarily sent.</p><p><b>Sent acknowledgement:</b> Accepted; response only.</p><p><b>Effective limits:</b> Sample readback differs from the last sent plan; not a profile inventory.</p><p><b>Measured now:</b> Sample 0.0 kW; separate from limits.</p><div class="actions"><wa-button size="small" disabled>Send · unavailable</wa-button><wa-button size="small" disabled>Refresh · unavailable</wa-button></div></div></wa-details>`, 'morek')}
${card('Recent charging', 'SAMPLE MEASURED HISTORY', `<div class="history-head"><div><strong>Yesterday · 22:00–23:00</strong><p class="subtext">Sample measured power · a gap stays unknown</p></div><wa-badge variant="success" pill>Meter example</wa-badge></div><div id="power-chart" class="chart power" role="img" aria-label="Sample measured charging power in kilowatts, with an unavailable measurement gap"></div><p class="subtext">Sample readings held for at most 15 minutes; the 22:30–22:45 gap is unknown. The steps are a display assumption, not continuous measurements.</p><div class="history-stats">${metric('Meter energy','6.0 kWh','Sample meter-counter difference')}${metric('Estimated cost','€0.48','Sample tariff · 8 c/kWh')}${metric('Sent plan','22:00–23:00','Observed flow during the window; gap prevents full comparison')}</div><div class="missing"><strong>Missing data example</strong><span>Previous session: energy unknown, not 0 kWh. A planned window is not measured history.</span></div>`, 'history')}
${card('Costs & savings', 'THIS CHARGE', `<div class="costs">${metric('Estimated energy',`${summary.energy.toFixed(1)} kWh`,'Three proposed windows')}${metric('Estimated cost',money(summary.cost),'EUR · variable price incl. fees & taxes')}${metric('Weighted average',`${summary.centsPerKwh.toFixed(2)} c/kWh`,'Total cost ÷ energy')}${metric('Historical savings','Unknown','Comparable baseline unavailable')}</div><div class="hint">Estimates are illustrative, not bills or measured energy. Missing prices or energy yield an unknown total, never zero.</div>`, 'costs-card')}
</div><footer>All data and illustrations are samples · No live data, commands or Home Assistant access · Visual design awaiting approval</footer></div>`;
document.querySelector('a[href="#details"]').addEventListener('click', () => { document.querySelector('#details').open = true; });
document.querySelector('.legend').insertAdjacentHTML('afterend', '<p class="subtext">For this illustration, published intervals at or below the cap are potential opportunities; shading identifies only the three proposed windows.</p>');
mountCharts();
